import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(): AIProvider {
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'hi'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('ChatOrchestrator hooks acceptance', () => {
  it('onError fires when beforeSession throws', async () => {
    const error = new Error('beforeSession failed');
    const onError = jest.fn();
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw error;
      },
      onError,
    };

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {hooks});
    const session = createSession('hello');

    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(onError).toHaveBeenCalledWith(session, error);
  });

  it('afterSession fires when beforeSession throws', async () => {
    const error = new Error('beforeSession failed');
    const afterSession = jest.fn();
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw error;
      },
      afterSession,
    };

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {hooks});
    const session = createSession('hello');

    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(afterSession).toHaveBeenCalledWith(session);
  });

  it('no other lifecycle hooks fire if beforeSession throws', async () => {
    const error = new Error('beforeSession failed');
    const beforeUserInput = jest.fn();
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw error;
      },
      beforeUserInput,
    };

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {hooks});
    const session = createSession('hello');

    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(beforeUserInput).not.toHaveBeenCalled();
  });
});

